import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
import "core-js/modules/es.iterator.for-each.js";
import DeleteMember from "@/components/DashBoard/Popups/DeleteMember.vue";
import SnackBar from "@/components/SnackBar.vue";
import { API, graphqlOperation } from "aws-amplify";
import { list_dashboard_users } from "@/graphql/queries.js";
export default {
  components: {
    SnackBar,
    DeleteMember
  },
  data() {
    return {
      tableLoading: false,
      memberdeltion: false,
      SnackBarComponent: {},
      memberdetails: {},
      componentCheck: 0,
      tableData: [],
      headers: [{
        title: "Email",
        key: "client_id",
        sortable: false
      }, {
        title: "Action",
        key: "Action",
        sortable: false
      }],
      currentPage: 1,
      itemsPerPage: 10,
      searchQuery: '',
      windowHeight: 0
    };
  },
  async mounted() {
    await this.get_dashboardSubcount();
    this.updateWindowHeight();
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.updateWindowHeight);
  },
  computed: {
    filteredItems() {
      if (!this.searchQuery || this.searchQuery.trim() === "") {
        return this.tableData;
      }
      const searchTerm = this.searchQuery.toLowerCase().trim();
      return this.tableData.filter(member => member.client_id?.toLowerCase().includes(searchTerm));
    },
    totalCount() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.filteredItems.length / this.itemsPerPage);
    },
    paginatedItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return this.filteredItems.slice(start, end);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    windowHeight() {
      return window.innerHeight - 310; // Adjust height based on header and padding
    }
  },
  watch: {
    searchQuery() {
      this.currentPage = 1;
    },
    currentPage() {
      // Scroll to top when page changes
      const table = document.querySelector(".modern-data-table");
      if (table) table.scrollIntoView({
        behavior: "smooth",
        block: "start"
      });
    }
  },
  methods: {
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.memberdeltion = false;
      this.tableData = [];
      this.currentPage = 1;
      this.searchQuery = '';
      this.get_dashboardSubcount();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    validate_delete(item) {
      this.memberdetails = item;
      this.memberdeltion = true;
      this.componentCheck = 1;
    },
    fetch_user_name(value) {
      var name = "";
      this.allUSersNames.forEach(element => {
        if (element.user_email_id == value) {
          name = element.full_user_name;
        }
      });
      return name;
    },
    async get_dashboardSubcount() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(list_dashboard_users, {
          input: {
            dashboard_id: this.$store.getters.GetdashboardDetails.dashboard_id
          }
        }));
        var response = JSON.parse(result.data.list_dashboard_users);
        this.tableLoading = false;
        if (response.Status == "Success") {
          this.tableData = [];
          this.tableData = response.Data;
        }
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    updateWindowHeight() {
      this.windowHeight = window.innerHeight - 310; // Adjust height based on header and padding
    }
  }
};
